		$v[0] = (string)$v[0];
		if (!isset($y[$v[0]])) {
			$y[$v[0]] = 0;
			$z[$v[0]] = 0;
		}
		$y[$v[0]] += $v[1];
		++$z[$v[0]];
	}
	unset($in);
	ksort($y, SORT_NUMERIC);
	ksort($z, SORT_NUMERIC);
	$x = array_keys($z);
	$y = array_values($y);
	$z = array_values($z);
	$count = count($z);
	echo n.$count.' : ';
	for ($k=0;$k<$count;++$k) {
		if (!($k % 1000)) echo $k.' ';
		$u = $d = 0;
		$usum = $dsum = 0;
		$walk = 0;
		while (true) {
			++$walk;
			if (isset($z[$k-$walk]) and $z[$k]+$z[$k-$walk]+$usum<$smooth) {
				$usum += $z[$k-$walk];
				$u += $y[$k-$walk];
